def peso(x):
    return "" if x is None or pd.isna(x) else f"₱{float(x):,.2f}"


def php_to_peso(text):
    """Stored letters and AI texts write 'PHP' (PDF fonts can't render ₱); the app shows ₱ (rule 6)."""
